body.script:
Store.Auth.requireAuth('admin');

function renderClientes() {
  const q     = document.getElementById('search-cli').value.toLowerCase().trim();
  const users = Store.Usuarios.clientes();
  const sols  = Store.Solicitudes.all();
  let clientes= users;
  if (q) clientes = clientes.filter(u => `${u.nombre} ${u.apellidos||''} ${u.email}`.toLowerCase().includes(q));

  document.getElementById('cli-footer').textContent = `${clientes.length} cliente${clientes.length!==1?'s':''}`;

  document.getElementById('cli-tbody').innerHTML = clientes.length===0
    ? `



Sin clientes`
    : clientes.map(u => {
        const mySols = sols.filter(s=>s.clienteId===u.id);
        const total  = mySols.filter(s=>s.estado==='aprobado').reduce((t,s)=>t+s.total,0);
        const ultimo = mySols.sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];
        const initials=(u.nombre[0]+(u.apellidos?u.apellidos[0]:'')).toUpperCase();
        return `





${initials}

${u.nombre} ${u.apellidos||''}


          ${u.email}
          ${u.telefono||'—'}
          ${mySols.length}
          ${UI.fmt.money(total)}
          ${ultimo?UI.fmt.date(ultimo.createdAt):'—'}



              Restablecer


        `;
      }).join('');
}

function resetPasswordAdmin(userId) {
  const u = Store.Usuarios.byId(userId);
  if (!u) return;
  UI.modal({
    title: 'Restablecer contraseña',
    body: `
Se generará una contraseña temporal para
           ${u.nombre} ${u.apellidos||''} (${u.email}).

La contraseña actual dejará de funcionar de inmediato. Comparte la nueva contraseña con el cliente por un canal seguro.`,
    confirmLabel: 'Generar contraseña',
    confirmClass: 'btn-primary',
    onConfirm: async () => {
      const result = await Store.Auth.adminResetPassword(userId);
      if (result.error) { UI.toast(result.error, 'error'); return; }
      showTempPassword(u, result.tempPassword);
    }
  });
}

function showTempPassword(u, temp) {
  UI.modal({
    title: 'Contraseña temporal generada',
    body: `

Nueva contraseña para ${u.nombre} ${u.apellidos||''}:


        ${temp}
        Copiar


Esta contraseña solo se muestra una vez. El cliente podrá cambiarla desde su perfil después de iniciar sesión.`,
    confirmLabel: 'Entendido',
    cancelLabel: 'Cerrar',
    confirmClass: 'btn-primary',
    onConfirm: () => {}
  });
}

function copyTempPass() {
  const val = document.getElementById('temp-pass-value').textContent;
  navigator.clipboard.writeText(val)
    .then(() => UI.toast('Contraseña copiada al portapapeles.', 'success'))
    .catch(() => UI.toast('No se pudo copiar automáticamente. Selecciona y copia manualmente.', 'warning'));
}

(async () => {
  try {
    await API.init(['solicitudes', 'usuarios']);
  } catch (err) { API.fatal(err); return; }
  renderSidebar('clientes-admin');
  renderClientes();
})();
